import{_ as a,o as t,c as o,an as s}from"./chunks/framework.CSf8ytFs.js";const g=JSON.parse('{"title":"FAQ / Gotchas","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":null}'),i={name:"faq.md"};function n(d,e,r,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="FAQ-/-Gotchas" tabindex="-1">FAQ / Gotchas <a class="header-anchor" href="#FAQ-/-Gotchas" aria-label="Permalink to &quot;FAQ / Gotchas {#FAQ-/-Gotchas}&quot;">​</a></h1><p>Common surprises and how to handle them.</p><h2 id="Aliases-for-clashing-names" tabindex="-1">Aliases for clashing names <a class="header-anchor" href="#Aliases-for-clashing-names" aria-label="Permalink to &quot;Aliases for clashing names {#Aliases-for-clashing-names}&quot;">​</a></h2><p>A few exports have aliases so you can avoid clashes with locals (especially when working inside HTMXObjects structs that often have a <code>data</code> field):</p><table tabindex="0"><thead><tr><th style="text-align:right;">Canonical</th><th style="text-align:right;">Alias</th><th style="text-align:right;">When to reach for the alias</th></tr></thead><tbody><tr><td style="text-align:right;"><code>data</code></td><td style="text-align:right;"><code>vdata</code></td><td style="text-align:right;">Your struct/closure has a field named <code>data</code></td></tr><tr><td style="text-align:right;"><code>to_node</code></td><td style="text-align:right;"><code>vdraw</code></td><td style="text-align:right;">You want a <code>draw</code>-shaped name without clashing with AoG&#39;s <code>draw</code> (which works on Makie figures, not VegaSpec)</td></tr><tr><td style="text-align:right;"><code>vlspec</code></td><td style="text-align:right;">—</td><td style="text-align:right;">Use to construct a raw Vega-Lite spec wrapper directly (no AoG needed)</td></tr></tbody></table><p>Both aliases call straight through to the canonical implementation — no behavioural difference.</p><div class="warning custom-block"><p class="custom-block-title">AoG&#39;s <code>draw</code> does not work on <code>VegaSpec</code> AlgebraOfGraphics&#39;s <code>draw</code> is for Makie figures and will error on a <code>VegaSpec</code>. Use <code>to_node(spec)</code> (or its alias <code>vdraw(spec)</code>) instead, or rely on the <code>Base.show</code> MIME hooks. :::</p><h2 id="Select-series-from-the-color-legend" tabindex="-1">Select series from the color legend <a class="header-anchor" href="#Select-series-from-the-color-legend" aria-label="Permalink to &quot;Select series from the color legend {#Select-series-from-the-color-legend}&quot;">​</a></h2><p>Click a categorical color legend entry to highlight its series. Other groups dim to 15% of their usual opacity; the data and axis ranges stay in place. Shift-click adds another group, and clicking blank plot space clears the selection.</p><p>This works with layer-local color encodings, facets, uncertainty bands and intervals, and per-column scale layouts, in live plots and standalone HTML. Layers and facets sharing a color field share one selection. Layers that color by <em>different</em> fields share one color scale, so Vega-Lite draws one merged legend for them (titled e.g. &quot;Vessel, Observation&quot;); each of its entries highlights the marks colored by that entry, whichever field they color by. An explicit independent color scale (<code>resolve</code>) draws a legend per layer, and each of those selects its own field. The channel picker rebuilds the selection when color changes.</p><p><code>interactive=false</code> disables automatic interaction. Explicit Vega-Lite <code>params</code> remain authoritative, as do conditional or data-driven opacity encodings. Continuous color scales, hidden legends, and Vega-Lite composite marks do not receive automatic legend selections.</p><h2 id="Light-and-dark-pages" tabindex="-1">Light and dark pages <a class="header-anchor" href="#Light-and-dark-pages" aria-label="Permalink to &quot;Light and dark pages {#Light-and-dark-pages}&quot;">​</a></h2><p>Plots follow the page&#39;s light/dark choice. The runtime draws axes, legends, facet headers, titles and unencoded text in the CSS <code>color</code> the plot element inherits, on a transparent background, so a plot inside a dark Pico page (or a dark card) reads as part of it. Palettes and literal mark colours stay fixed. For a fixed line or point that should use the page&#39;s foreground ink, write <code>visual(Lines; color=:ink)</code> (or use another mark type, a ribbon — <code>lineribbon(...) * visual(; color=:ink)</code> — or an interval analysis: <code>pointinterval() * visual(; color=:ink)</code>). To ink one side of a mark only, write <code>stroke=:ink</code> (or Makie&#39;s <code>strokecolor=:ink</code>) or <code>fill=:ink</code>, as in <code>visual(; fill=nothing, stroke=:ink)</code> for a map outline. The same spec uses the active Makie theme&#39;s text colour with <code>sdraw</code> (where the analysis has a static lowering); PNG/SVG browser downloads use the page&#39;s colour and background. When the page switches theme (<code>prefers-color-scheme</code>, or a <code>class</code> / <code>data-theme</code> / <code>style</code> change on <code>&lt;html&gt;</code> or <code>&lt;body&gt;</code>) the plots re-render in place, keeping the channel-picker assignment, <code>update_spec</code> data and streamed rows. After switching a theme some other way (a class on a wrapper element), call <code>AoV.refreshTheme()</code>.</p><ul><li><p>Do not style the chrome with <code>currentColor</code> in <code>config(config=...)</code>: Vega&#39;s canvas renderer paints <code>currentColor</code> black. A spec&#39;s own <code>config</code> values still win over the theme, key by key.</p></li><li><p>Do not invert the canvas with a CSS <code>filter</code> — it recolours the palette too.</p></li><li><p>PNG/SVG downloads of a plot are painted on the page background behind it.</p></li><li><p><code>vega_head(theme=:none)</code> (page) or <code>config(theme=:none)</code> (one plot) keeps Vega&#39;s own look: white background, black text.</p></li></ul><h2 id="Faceting-select-interactions" tabindex="-1">Faceting + <code>select=</code> interactions <a class="header-anchor" href="#Faceting-select-interactions" aria-label="Permalink to &quot;Faceting + `select=` interactions {#Faceting-select-interactions}&quot;">​</a></h2><p><code>config(select=:origin)</code> adds a client-side dropdown that filters the data frame <em>before</em> it reaches any layer. When you also use faceting (<code>row=</code> / <code>col=</code> channels), the filter applies to <em>all</em> facets — there&#39;s no per-facet dropdown. If you want per-facet interaction, use <code>mapping_controls</code> + <code>auto_remap_node</code> instead.</p><h2 id="Animate-over-a-column-frame" tabindex="-1">Animate over a column (<code>frame=</code>) <a class="header-anchor" href="#Animate-over-a-column-frame" aria-label="Permalink to &quot;Animate over a column (`frame=`) {#Animate-over-a-column-frame}&quot;">​</a></h2><p><code>config(frame=:year)</code> shows one value of a column at a time, with a play/pause button, a slider and the current value under the plot. Play steps through the values in order and stops on the last one.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(anomalies) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> mapping</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:land</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; color</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:anomaly</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> geoshape</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;geo/laender.geojson&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(frame</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; field</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:year</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, interval</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, loop</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><ul><li><p>Rows whose frame value is missing, and layers without the frame column (a base map, a reference line), are drawn in every frame.</p></li><li><p>Colour, size and x/y scales keep one domain across all frames, so a colour means the same value in every frame and axes do not jump. A map keeps one projection fit. Stacked bars and Vega-Lite transforms such as unfaceted <code>density()</code> or <code>linear()</code> are recomputed per frame, still on the shared axes.</p></li><li><p>Frames play in sorted order, or in a <code>sorter</code> order: <code>frame=:month =&gt; sorter(&quot;Jan&quot;, &quot;Feb&quot;, …)</code>. Options: <code>interval</code> (seconds per frame, default 0.5), <code>loop</code> (default <code>false</code>) and <code>start</code> (<code>:first</code>, <code>:last</code> or a frame value).</p></li><li><p>It works in live pages and in static exports (<code>to_html</code>, the &quot;⬇ HTML&quot; download), wherever AoV&#39;s runtime is on the page. The controls&#39; words come from <code>plot_texts</code> (<code>play</code>, <code>pause</code>).</p></li><li><p>The page can drive a player through <code>AoV.setFrame(id, index)</code>, <code>AoV.playFrames(id)</code> and <code>AoV.pauseFrames(id)</code>.</p></li><li><p>Boundaries: <code>sdraw</code> refuses frames. Summaries AoV computes in Julia from raw draws (<code>pointinterval()</code>, <code>lineribbon()</code>, faceted or ridgeline <code>density()</code>) cannot step through frames: summarise per frame yourself and use the <code>bands=</code> form. Refresh a framed plot with <code>update_spec</code>; <code>append_data</code> and the other raw-row operations are refused. In a facet with a single layer, a panel with no rows in the shown frame is not drawn in that frame. Independent facet scales (<code>linkyaxes=:none</code>, per-column Y scales) fit each panel to the shown frame.</p></li></ul><h2 id="Deep-merged-encoding" tabindex="-1">Deep-merged encoding <a class="header-anchor" href="#Deep-merged-encoding" aria-label="Permalink to &quot;Deep-merged encoding {#Deep-merged-encoding}&quot;">​</a></h2><p>When you pass <code>config(encoding = (; x = (; scale = (; type = &quot;log&quot;))))</code>, AoV <strong>deep-merges</strong> that into the encoding dict it generated from <code>mapping(...)</code>. So you can override (or add to) any auto-generated channel without re-specifying it from scratch:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(df) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> mapping</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:y</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> visual</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Scatter) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(encoding </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (; scale </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (; type </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;log&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)),</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    tooltip </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [(; field</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), (; field</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:y</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), (; field</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:group</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)],   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># extra tooltip fields</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>The <code>Dict</code> spelling is equivalent: <code>config(encoding = Dict(&quot;x&quot; =&gt; Dict(&quot;scale&quot; =&gt; Dict(&quot;type&quot; =&gt; &quot;log&quot;))))</code>. Keys may be Symbols or Strings, and Symbol values such as <code>field=:x</code> become the strings Vega-Lite reads. Raw <code>config(config = (; …))</code> is deep-merged the same way into AoV&#39;s default Vega-Lite config. Any other value (a string, <code>nothing</code>, …) is rejected by <code>config(...)</code> with an <code>ArgumentError</code>.</p><p>If the override doesn&#39;t take effect, the most likely cause is a typo in a channel or property name — names must match Vega-Lite&#39;s exactly.</p><h2 id="When-to-use-pregrouped" tabindex="-1">When to use <code>pregrouped()</code> <a class="header-anchor" href="#When-to-use-pregrouped" aria-label="Permalink to &quot;When to use `pregrouped()` {#When-to-use-pregrouped}&quot;">​</a></h2><p>AoG&#39;s <code>pregrouped(xs, ys, ...)</code> is the right hook when your data is already in nested-vector shape (one element per group). AoV passes through to AoG&#39;s own grouping behaviour. Use it when you have e.g. a <code>Vector{Vector{Float64}}</code> of curves and don&#39;t want to flatten + tag with a group column first.</p><h2 id="lineribbon-vs-ribbon-vs-precomputed-bands" tabindex="-1"><code>lineribbon</code> vs <code>ribbon</code> vs precomputed bands <a class="header-anchor" href="#lineribbon-vs-ribbon-vs-precomputed-bands" aria-label="Permalink to &quot;`lineribbon` vs `ribbon` vs precomputed bands {#lineribbon-vs-ribbon-vs-precomputed-bands}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">You have</th><th style="text-align:right;">Use</th></tr></thead><tbody><tr><td style="text-align:right;">Long-format draws (one row per draw × x)</td><td style="text-align:right;"><code>lineribbon</code> — computes intervals from draws</td></tr><tr><td style="text-align:right;">Long-format draws + you want only the band (no centre line)</td><td style="text-align:right;"><code>ribbon</code></td></tr><tr><td style="text-align:right;">Precomputed <code>lo</code>/<code>hi</code> columns</td><td style="text-align:right;"><code>lineribbon(...; bands=[:lo50 =&gt; :hi50, :lo95 =&gt; :hi95])</code> (or <code>ribbon(...; bands=…)</code>) — <code>bands</code> is a vector of <code>lo =&gt; hi</code> Pairs of column names; skips the draw-based estimator</td></tr></tbody></table><p>All three take a fixed colour the way a plain mark does — <code>lineribbon(bands=…) * visual(; color=&quot;black&quot;)</code> (or <code>color=:ink</code>) colours every band and the median line. A <code>color=</code> mapping wins over it; other <code>visual</code> attributes are not applied to ribbons and log a warning.</p><p>A ribbon coloured by <code>color=</code> over at most 12 numeric x values (a dose ladder) is also drawn as point-intervals, and a &quot;Ribbons | Intervals&quot; switch in the browser swaps the two drawings. The figure starts in point-intervals when the colour groups&#39; outer bands overlap by more than 10% of the y range; <code>lineribbon(...; intervals=0.25)</code> changes that threshold, and <code>intervals=true</code>/<code>false</code> fix the start. The point-intervals keep the ribbon&#39;s x axis, a log scale included, with each colour group a small step either side of the true x; observations and dose <code>VLines</code> stay where they are. The axis leaves room for the outermost groups at the first and last x, and a log axis is not rounded out to the next power of ten. When the x values are too unevenly spaced on that axis to dodge readably (a doubling dose ladder on a linear axis), the point-intervals sit on evenly spaced x slots instead.</p><p>The interval analyses take a fixed colour the same way: <code>pointinterval() * visual(; color=&quot;black&quot;)</code> (also <code>bands=</code>, <code>gradient_interval()</code> and <code>dotinterval()</code>) colours every interval rule — and <code>dotinterval</code>&#39;s dots — in place of the per-category palette colour, while the median point stays white with a dark ring. A <code>color=</code> mapping wins here too.</p><p>See the <a href="/AlgebraOfVega.jl/dev/api#tidybayes-style-uncertainty-analyses">API Reference</a> for the full docstring set and the <a href="./gallery">Gallery</a> for worked examples.</p><h2 id="CDN-versions-and-offline-rendering" tabindex="-1">CDN versions and offline rendering <a class="header-anchor" href="#CDN-versions-and-offline-rendering" aria-label="Permalink to &quot;CDN versions and offline rendering {#CDN-versions-and-offline-rendering}&quot;">​</a></h2><p><code>vega_head()</code> injects tags for the exact-pinned trio in <code>vega_cdn_urls()</code> (a <code>Vector</code> of three URL strings — Vega, Vega-Lite, Vega-Embed in that order), with subresource-integrity hashes (<code>vega_sri_hashes()</code>), so a CDN-side release can never change rendering with zero repo diff. Override <code>vega_version=</code> / <code>vegalite_version=</code> / <code>vega_embed_version=</code> only with <code>source=:cdn</code> (a custom version opts out of SRI, since the hash would not match).</p><p>For offline use, AoV vendors the same builds under <code>vendor/</code>: <code>vega_head(; source=:vendor, base=&quot;/vendor&quot;)</code> emits same-origin tags (serve <code>vega_vendor_dir()</code> at <code>base</code> from your app), and <code>source=:inline</code> inlines the bytes. <code>to_html(...; source=:inline)</code> writes a standalone file that renders with no network at all.</p><p>AoV&#39;s own runtime (<code>aov-runtime.js</code>) and stylesheet (<code>aov.css</code>), about 96 KB, are inlined into every page by default. With the vendor mount, <code>vega_head(; source=:vendor, base=&quot;/vendor&quot;, runtime=:linked)</code> loads them from that directory too, so each full page carries a few hundred bytes of tags that the browser caches. Every vendor URL ends in <code>?v=&lt;content hash&gt;</code>, which changes exactly when the file does, so the mount may use a far-future cache lifetime — with HTMXObjects: <code>staticfiles(vega_vendor_dir(), &quot;vendor&quot;; headers=[&quot;Cache-Control&quot; =&gt; &quot;public, max-age=31536000, immutable&quot;])</code>. Page settings (<code>zoom</code>, <code>max_width</code>, <code>actions</code>, <code>theme</code>) stay a small inline script. A captioned plot&#39;s &quot;⬇ HTML&quot; download inlines the vendored files the page loaded, so the saved card still renders with no server and no CDN.</p><h2 id="My-spec-doesn&#39;t-render-and-I-get-no-error" tabindex="-1">&quot;My spec doesn&#39;t render and I get no error&quot; <a class="header-anchor" href="#My-spec-doesn&#39;t-render-and-I-get-no-error" aria-label="Permalink to &quot;&quot;My spec doesn&#39;t render and I get no error&quot; {#&quot;My-spec-doesn&#39;t-render-and-I-get-no-error&quot;}&quot;">​</a></h2><p>Vega-Lite is forgiving — it&#39;ll silently render a blank chart for a malformed spec. Two debugging moves:</p><ol><li><p><strong><code>println(to_json(spec))</code></strong> — inspect the actual Vega-Lite JSON being emitted.</p></li><li><p>Open browser DevTools, paste the JSON into the <a href="https://vega.github.io/editor/#/edited" target="_blank" rel="noreferrer">Vega Editor</a> — it produces actionable errors in a way the embed runtime doesn&#39;t.</p></li></ol><h2 id="HTMX-update_data-doesn&#39;t-refresh" tabindex="-1">HTMX + <code>update_data</code> doesn&#39;t refresh <a class="header-anchor" href="#HTMX-update_data-doesn&#39;t-refresh" aria-label="Permalink to &quot;HTMX + `update_data` doesn&#39;t refresh {#HTMX-update_data-doesn&#39;t-refresh}&quot;">​</a></h2><p><code>update_data(id, new_rows)</code> works only when the rendered spec was given the same <code>id</code>. The <code>id</code> is a kwarg to <code>to_node</code>, not <code>config</code>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">to_node</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(spec; id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-plot-1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># render with stable id</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">update_data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-plot-1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, new_rows)       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># later, push new rows from a route handler</span></span></code></pre></div><p>If you don&#39;t set an explicit <code>id</code>, AoV assigns one automatically — but the update handler can&#39;t guess it. Always set an explicit <code>id</code> for any spec you intend to update from a server endpoint.</p></div>',7)])])}const k=a(i,[["render",n]]);export{g as __pageData,k as default};
